#![cfg(windows)]

//! `playVideo` 通过 C++ 渲染器的 Media Foundation 探测时长，
//! 并把后续语句排到视频结束之后。

use std::fs;
use std::path::Path;

use webgal_video_export::api::{ExportOptions, build_plan};
use webgal_video_export::plan::AudioKind;

const CLIP: &[u8] = include_bytes!("fixtures/video/clip.mp4");

fn write(root: &Path, relative: &str, bytes: &[u8]) {
    let path = root.join(relative);
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).expect("create dir");
    }
    fs::write(path, bytes).expect("write fixture");
}

#[test]
fn play_video_advances_the_timeline_and_adds_its_audio() {
    let directory = tempfile::tempdir().expect("temp dir");
    let root = directory.path();
    write(root, "game/config.txt", b"Game_name:Video;\n");
    write(root, "game/video/clip.mp4", CLIP);
    write(
        root,
        "game/scene/start.txt",
        b"playVideo:clip.mp4;\nsay:after;\nend;\n",
    );

    let plan = build_plan(&ExportOptions::new(root)).expect("build plan");

    assert_eq!(plan.videos.len(), 1);
    assert_eq!(plan.videos[0].start_us, 0);
    let duration = plan.videos[0].end_us;
    assert!(
        (900_000..=1_100_000).contains(&duration),
        "1 秒视频的探测时长异常: {duration}"
    );
    assert_eq!(plan.videos[0].path, "video/clip.mp4");
    assert_eq!(plan.assets["video/clip.mp4"].duration_us, Some(duration));

    // 后续对白必须从视频结束处开始，而不是和视频重叠。
    assert_eq!(plan.texts[0].start_us, duration);

    let video_audio = plan
        .audio
        .iter()
        .find(|event| event.kind == AudioKind::Video)
        .expect("视频音轨事件");
    assert_eq!(video_audio.start_us, 0);
    assert_eq!(video_audio.end_us, Some(duration));
    assert_eq!(video_audio.path, "video/clip.mp4");
    // WebGAL 的视频音量取 BGM 音量；默认 bgmVolume 是 25。
    assert!((video_audio.volume - 0.25).abs() < 1e-6);
}

#[test]
fn disabling_audio_keeps_the_video_picture() {
    let directory = tempfile::tempdir().expect("temp dir");
    let root = directory.path();
    write(root, "game/config.txt", b"Game_name:Video;\n");
    write(root, "game/video/clip.mp4", CLIP);
    write(root, "game/scene/start.txt", b"playVideo:clip.mp4;\nend;\n");

    let mut options = ExportOptions::new(root);
    options.config.include_audio = false;
    let plan = build_plan(&options).expect("build plan");

    assert_eq!(plan.videos.len(), 1);
    assert!(plan.audio.is_empty());
}

#[test]
fn unreadable_video_is_reported_instead_of_silently_skipped() {
    let directory = tempfile::tempdir().expect("temp dir");
    let root = directory.path();
    write(root, "game/config.txt", b"Game_name:Video;\n");
    write(root, "game/video/bad.mp4", b"not a video");
    write(root, "game/scene/start.txt", b"playVideo:bad.mp4;\nend;\n");

    let error = build_plan(&ExportOptions::new(root)).expect_err("坏容器应报错");
    assert!(error.to_string().contains("无法探测视频时长"), "{error}");
}
